__all__ = ["check_ecpri_ru_transmit_power_in_normal_range"]


RU_TRANSMIT_POWER_CHECK_LIST = ["AEHC", "AEQZ", "AEQC", "AEQQ", "AEQV", "AEQY", "AQQA", "AQQC", "AQQY"]

SUPPORTING_RELEASE = ["23R1", "23R2"]


class RUPowerCheckFailed(ExecutionFailed):
    def __init__(self, message):
        super(RUPowerCheckFailed, self).__init__(message=message, exit=True)


def transmit_log(message, level="INFO"):
    msg = "[RTPC] {}".format(message)
    if level == "WARN":
        logging.warning(msg)
    elif level == "ERROR":
        logging.error(msg)
    elif level == "EXCEPT":
        logging.exception(msg)
    else:
        logging.info(msg)


def check_ecpri_ru_transmit_power_in_normal_range(pass_ru_power_check=False):
    rfs = None
    if pass_ru_power_check:
        transmit_log("Directly pass the check as pass_ru_power_check={}".format(pass_ru_power_check))
        return
    try:
        tl = BuiltIn().get_variable_value("${tl}")
        invalid_results = []
        verified_rus = []
        primary_list = []
        if not tl:
            transmit_log(
                "Current version only support environment using tl for configuration storage."
            )
            return
        if not isinstance(tl, TestLine):
            transmit_log("Have support environment not using taf.config.testline")
            return
        if tl.gnbs:
            if TestlineInfo.get_number_of_du(tl):
                primary_list += TestlineInfo.get_du_list(tl)
        if TestlineInfo.has_enb(tl):
            primary_list += TestlineInfo.get_real_enbs(tl)
        if not primary_list:
            transmit_log("Only support environments have gNB or real enb yet.")
            return
        for primary in primary_list:
            # Check if testline is supported type, and return correct host/username/password if supported.
            # This first draft only support 5G gnb environment with DU.
            primary_login_info = get_host_info_from_primary(primary)
            if primary_login_info:
                primary_host, primary_username, primary_password = primary_login_info
            else:
                continue
            cells, hw_info, sw_version, release = get_ru_info_via_admin(primary_host, primary_username, primary_password)
            if release not in SUPPORTING_RELEASE:
                transmit_log("Haven't support this release SW version {}".format(sw_version))
                return
            if not cells:
                transmit_log(
                    "Current version only support environment with nr cell or lte cell."
                )
                continue
            cell_config_rmod = get_rmod_config_info_for_cell(cells)
            if not cell_config_rmod:
                transmit_log("Ignore this DU due to none enable cell detected.")
                continue
            ru_list = hw_info["radioModules"]["rmod"]
            if not ru_list:
                transmit_log("No RU detected, Ignore testline.")
                continue
            ru_dict = generate_ru_dict(ru_list, cell_config_rmod)
            if not ru_dict:
                transmit_log("Bypass due to empty RU dict generated.")
                continue
            ru_raws, hostname = get_ru_connection_info_via_ssh(primary_host, primary_username, primary_password)
            du_config = {'host': primary_host, 'username': primary_username, "password": primary_password}
            container_id = get_container_id_from_hostname(hostname)
            if not container_id:
                transmit_log("Not adapted FHNET container, bypass for now.")
                continue
            lxc_config = generate_lxc_config(du_config=du_config, container_id=container_id)
            ru_configs = update_ru_queue(ru_raws=ru_raws, verified_rus=verified_rus)
            rfs = RfswSsh()
            prepare_rus = []
            if len(ru_configs) == 0:
                transmit_log("None linked RU supported, pass this DU.")
                continue
            else:
                for index, ru_config in enumerate(ru_configs, 0):
                    if index == 0:
                        prepare_rus.append(rfs.prepare_ru(ru_name=ru_configs[0]["type"],
                                                          hops=[du_config, lxc_config],
                                                          ru_ssh_service=ru_configs[0]["config"],
                                                          release=release.lower(),
                                                          initialization_commands=["rm -f /usr/toor4nsn/.ssh/known_hosts"]
                                                          ))
                    else:
                        prepare_rus.append(rfs.prepare_next_ru(ru_name=ru_config["type"],
                                                               ru_ssh_service=ru_config["config"]))
            validate_tx_power_on_prepared_ru(rfs, prepare_rus, invalid_results)
        if invalid_results:
            for i in invalid_results:
                transmit_log(
                    "{} meeting RU transmit power issue, power value: {}".format(i["RU"], i["power"]),
                    level="ERROR"
                )
            raise RUPowerCheckFailed("Found invalid transmit power.")
        else:
            transmit_log("Power check pass", level="INFO")
            return True
    except RUPowerCheckFailed as err:
        raise err
    except AdminApiConnectionClosedException:
        transmit_log("Admin connection creation failure, please check the environment.")
    except Exception:
        transmit_log(logging.traceback.format_exc())
        transmit_log("Meeting unexpected error. Pass the keyword, "
                     "kindly contact keyword owner with error info for better adaption.",
                     level="ERROR")
    finally:
        if rfs:
            rfs.release()


def get_rmod_config_info_for_cell(cells):
    cell_config_rmod = []
    # Get enabled cells, ignore power check for locked cells.
    for cell in cells:
        if (
                cell["status"]["administrativeState"].lower() != "unlocked"
                or cell["status"]["operationalState"].lower() != "enabled"
        ):
            transmit_log("Cell not on air, ignore this cell")
            continue
        if not cell["carrierList"][0]["antennaLineId"]:
            transmit_log("antennaLineId not configured, ignore this cell")
            continue
        cell_config_rmod.append(
            cell["carrierList"][0]["antennaLineId"]["configuration"]
            .split("RMOD-")[-1]
            .split("/")[0]
        )
    return cell_config_rmod


def generate_ru_dict(ru_list, cell_config_rmod):
    ru_dict = {}
    for ru in ru_list:
        if ru["id"]["configuration"].split("RMOD-")[1] not in cell_config_rmod:
            continue
        if ru["status"]["operationalState"].lower() != "enabled":
            transmit_log("RU not enabled, ignore this RU.{}".format(ru))
            continue
        try:
            ru_dict[ru["serialNumber"]] = ru["id"]["configuration"].split("RMOD-")[1]
        except IndexError as err:
            transmit_log("By Pass RU due to: {}".format(err))
            continue
    return ru_dict


def update_ru_queue(ru_raws, verified_rus):
    ru_configs = []
    for ru_raw in ru_raws:
        ru_ip = ru_raw.split(";")[0]
        # rmod_index = ru_dict[ru_raw.split(";")[1]]
        ru_type = ru_raw.split(";")[2]
        new_config = {"type": ru_type, "config": {"host": ru_ip}}
        if ru_type not in RU_TRANSMIT_POWER_CHECK_LIST:
            logging.info("Not supported RU {}, ignore.".format(new_config))
            continue
        if new_config not in verified_rus:
            verified_rus.append(new_config)
            ru_configs.append(new_config)
            logging.info("Adding {} into check queue".format(new_config))
    return ru_configs


def get_host_info_from_primary(primary):
    if isinstance(primary, DU):
        if primary.f1_m_ip_addr:
            if isinstance(primary.f1_m_ip_addr, str):
                host = primary.f1_m_ip_addr
            elif isinstance(primary.f1_m_ip_addr, NetworkAddress):
                host = primary.f1_m_ip_addr.v4 if primary.f1_m_ip_addr.v4 else primary.f1_m_ip_addr.v6
            else:
                transmit_log("Invalidate f1_m_ip_addr type configured, not to check on this env.")
                return
        elif primary.airscale.common_units:
            host = primary.airscale.common_units[0].lmp_connection.addr
        elif primary.airscale.core_units:
            host = primary.airscale.core_units[0].lmp_connection.addr
        else:
            transmit_log("Testline configuration missing cu, not supported.")
            return

        if primary.airscale.core_units:
            username = primary.airscale.core_units[0].lmp_connection.username
            password = primary.airscale.core_units[0].lmp_connection.password
        else:
            username = primary.airscale.common_units[0].lmp_connection.username
            password = primary.airscale.common_units[0].lmp_connection.password

    elif isinstance(primary, RealEnb):
        if primary.oam_ip:
            if isinstance(primary.oam_ip, str):
                host = primary.oam_ip
            elif isinstance(primary.oam_ip, NetworkAddress):
                host = primary.oam_ip.v4 or primary.oam_ip.v6
            else:
                transmit_log("Invalidate oam_ip type configured in enb, not to check on this env.")
                return
        else:
            transmit_log("Missing OAM host info, not supported yet.")
            return
        if not primary.system_module:
            transmit_log("Missing system_module in eNB.")
        if isinstance(primary.system_module, list):
            username = primary.system_module[0].lmp_connection.username
            password = primary.system_module[0].lmp_connection.password
        elif isinstance(primary.system_module, SystemModule):
            username = primary.system_module.common_units[0].lmp_connection.username
            password = primary.system_module.common_units[0].lmp_connection.password
        else:
            transmit_log("Not SystemModule type, not to check this env.")
            return
    else:
        transmit_log("Not supported testline type.")
        return
    return host.split('/')[0], username, password


def validate_tx_power_on_prepared_ru(rfs, prepare_rus, invalid_results, process_num=None):
    logging.info("Created pool to check RU transmit power.")
    pn = process_num or cpu_count()
    logging.info("Create {} thread pool".format(pn))
    pool = Pool(pn)
    async_results = []
    for prepare_ru in prepare_rus:
        logging.info("Checking prepare RU {}".format(prepare_ru))
        async_results.append(pool.apply_async(retrieve_tx_power_from_prepared_ru,
                                              kwds={"rfs": rfs, "prepare_ru": prepare_ru}))
    pool.close()
    pool.join()
    for ar in async_results:
        result = ar.get()
        if result["invalid"]:
            for iv in result["invalid"]:
                invalid_results.append(iv)
                logging.info("{}'s power value: {}".format(iv["RU"], iv["power"]))
        if result["valid"]:
            for v in result["valid"]:
                logging.info("{}'s power value: {}".format(v["RU"], v["power"]))

    logging.info("Check finished in this DU.")


def retrieve_tx_power_from_prepared_ru(rfs, prepare_ru):
    powers = rfs.retrieve_tx_power(try_sudo=True, ru=prepare_ru)
    results = {"invalid": [], "valid": []}
    for power in powers:
        if "DPD IN" not in power:
            continue
        if not re.findall(r"-([1-9]\d*\.\d*|0\.\d*[1-9]\d*)", str(power)):
            results["invalid"].append({"RU": prepare_ru.name,
                                       "power": powers})
        else:
            results["valid"].append({"RU": prepare_ru.name,
                                     "power": powers})
    return results


def get_ru_info_via_admin(du_host, du_username, du_password):
    admin_connection = AdminConnection(bts_host=du_host, username=du_username, password=du_password)
    nr_cells = admin_connection.get_cells_info(cell_type="nr", timeout=20)
    lte_cells = admin_connection.get_cells_info(cell_type="lte", timeout=20)
    cells = nr_cells + lte_cells
    hw_info = admin_connection.get_detected_hw_info()
    sw_version = admin_connection.get_sw_version()
    release = get_release_from_sw_version(sw_version)
    disconnect_and_ignore_errors(admin_connection)
    return cells, hw_info, sw_version, release


def get_ru_connection_info_via_ssh(du_host, du_username, du_password):
    ssc = SSHConnection()
    ssc.configure(
        hostname=du_host,
        username=du_username,
        password=du_password,
    )
    ssc.connect()
    ru_raws = ssc.execute("cat /ffs/run/config/FRIps.txt |cut -d ';' -f 3-5", timeout=5).split()
    hostname = ssc.execute("hostname")
    disconnect_and_ignore_errors(ssc)
    return ru_raws, hostname


def disconnect_and_ignore_errors(cnt):
    try:
        cnt.disconnect()
    except Exception:
        pass


def get_release_from_sw_version(sw_version):
    releases = [
        "22R2",
        "22R3",
        "22R4",
        "23R1"
    ]
    for release in releases:
        if release in sw_version:
            return release
    else:
        return "Undefined"


def get_container_id_from_hostname(hostname):
    if "fct-0a" in hostname or "asc-0a" in hostname:
        return "0x1018"
    elif "fct-4a" in hostname:
        return "0x2018"
    else:
        return None


